    live.clear();for(const [id,v] of proposal)live.set(id,v);
    versions.set(r.id,{rev:r.rev,payload:canonical(r)});
    finalize();
  }
  const result=[...sealed,...components(live)];result.sort((a,b)=>a.start-b.start||ascii(a.key,b.key));
